CREATE TABLE schools (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL);
CREATE TABLE school_domains (domain text PRIMARY KEY CHECK(domain=lower(domain)), school_id uuid NOT NULL REFERENCES schools);
CREATE TABLE terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools, name text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL CHECK(starts_on<=ends_on));
CREATE TABLE term_slots (term_id uuid REFERENCES terms, slot_code smallint CHECK(slot_code/100 BETWEEN 1 AND 7 AND slot_code%100 BETWEEN 1 AND 99), starts_at time NOT NULL, ends_at time NOT NULL CHECK(starts_at<ends_at), PRIMARY KEY(term_id,slot_code));
CREATE TABLE places (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE app_settings (id integer PRIMARY KEY CHECK(id=1), school_id uuid NOT NULL REFERENCES schools, current_term_id uuid NOT NULL REFERENCES terms, registration_open boolean NOT NULL DEFAULT false, service_ends_on date NOT NULL, privacy_version text NOT NULL, privacy_notice jsonb NOT NULL, launch_verified_at timestamptz);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), school_id uuid NOT NULL REFERENCES schools, email text NOT NULL UNIQUE, display_name text CHECK(length(display_name)<=100), department text CHECK(length(department)<=100), entry_year integer, interests text[] NOT NULL DEFAULT '{}', privacy_version text NOT NULL, privacy_acknowledged_at timestamptz NOT NULL, optional_profile_consented_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE otp_challenges (id uuid PRIMARY KEY, school_id uuid NOT NULL REFERENCES schools, email text NOT NULL UNIQUE, code_hmac text NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 4), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE auth_limits (kind text CHECK(kind IN ('email','ip')), key_hmac text, count integer NOT NULL, window_started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, last_sent_at timestamptz, PRIMARY KEY(kind,key_hmac));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE availability (user_id uuid REFERENCES users ON DELETE CASCADE, term_id uuid REFERENCES terms, slots smallint[] NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,term_id));
CREATE TABLE meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), host_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, term_id uuid NOT NULL REFERENCES terms, topic text NOT NULL CHECK(length(btrim(topic)) BETWEEN 1 AND 100), type text NOT NULL CHECK(type IN ('study','coffee','lunch')), place_id uuid NOT NULL REFERENCES places, capacity integer NOT NULL DEFAULT 3 CHECK(capacity BETWEEN 2 AND 4), state text NOT NULL DEFAULT 'undecided' CHECK(state IN ('undecided','proposing','confirmed')), confirmed_date date, confirmed_slot smallint, confirmation_source text CHECK(confirmation_source IN ('intersection','proposal')), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days', version bigint NOT NULL DEFAULT 1, next_member_no integer NOT NULL DEFAULT 2, CHECK((state='confirmed' AND confirmed_date IS NOT NULL AND confirmed_slot IS NOT NULL AND confirmation_source IS NOT NULL) OR (state<>'confirmed' AND confirmed_date IS NULL AND confirmed_slot IS NULL AND confirmation_source IS NULL)));
CREATE TABLE meeting_members (meeting_id uuid REFERENCES meetings ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, member_no integer NOT NULL CHECK(member_no>0), joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(meeting_id,user_id), UNIQUE(meeting_id,member_no));
CREATE TABLE meeting_overrides (meeting_id uuid, user_id uuid, slots smallint[] NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(meeting_id,user_id), FOREIGN KEY(meeting_id,user_id) REFERENCES meeting_members ON DELETE CASCADE);
CREATE TABLE proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings ON DELETE CASCADE, proposed_date date NOT NULL, proposed_slot smallint NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','cancelled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_proposal ON proposals(meeting_id) WHERE status='pending';
CREATE TABLE proposal_acceptances (proposal_id uuid REFERENCES proposals ON DELETE CASCADE, user_id uuid REFERENCES users ON DELETE CASCADE, accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(proposal_id,user_id));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, author_member_no integer NOT NULL, body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, target_user_id uuid REFERENCES users ON DELETE CASCADE, target_meeting_id uuid REFERENCES meetings ON DELETE CASCADE, reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','upheld','dismissed')), reviewed_at timestamptz, reviewer_id text, review_reason text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days', CHECK((target_user_id IS NULL)<>(target_meeting_id IS NULL)), CHECK(target_user_id IS NULL OR target_user_id<>reporter_id));
CREATE TABLE blocks (blocker_id uuid REFERENCES users ON DELETE CASCADE, blocked_id uuid REFERENCES users ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id));
-- Delivery outbox has no account FK and contains only opaque IDs and deletion times.
CREATE TABLE deletion_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL, deleted_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE INDEX meetings_listing ON meetings(term_id,created_at DESC,id DESC);
CREATE INDEX members_user ON meeting_members(user_id,meeting_id);
CREATE INDEX comments_listing ON comments(meeting_id,created_at,id);
CREATE INDEX proposals_listing ON proposals(meeting_id,created_at);
CREATE INDEX reports_restriction ON reports(target_user_id,reporter_id,expires_at) WHERE status<>'dismissed' AND target_user_id IS NOT NULL;
CREATE INDEX blocks_reverse ON blocks(blocked_id,blocker_id);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX otp_expiry ON otp_challenges(expires_at);
CREATE INDEX meetings_expiry ON meetings(expires_at);
CREATE INDEX reports_expiry ON reports(expires_at);
CREATE INDEX auth_limits_expiry ON auth_limits(expires_at);
